(()=>{'use strict';const productUrl=id=>'/smartgift/products/'+(Number(id)>=900000?'sg-':'gu-')+id;const sku=id=>(Number(id)>=900000?'SG-':'GU-')+id;const base='/smartgift',key='smartgift-quote-v2';const $=(s,r=document)=>r.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let basket=[];try{basket=JSON.parse(localStorage.getItem(key)||'[]').filter(x=>/^\d+$/.test(x.id)&&Number.isInteger(x.quantity)&&x.quantity>0).slice(0,100)}catch{}let catalogPromise,featuredPromise;const fetchJson=async u=>{const r=await fetch(u);if(!r.ok)throw Error('โหลดข้อมูลไม่สำเร็จ');return r.json()};const catalog=()=>catalogPromise||(catalogPromise=fetchJson('/data/catalog.json').then(d=>d.items).catch(e=>{catalogPromise=null;throw e}));const featured=()=>featuredPromise||(featuredPromise=fetchJson('/data/featured.json'));function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2800)}function sync(){document.querySelectorAll('[data-basket-count]').forEach(el=>el.textContent=basket.length);document.querySelectorAll('[data-add]').forEach(el=>{const added=basket.some(p=>p.id===el.dataset.add);el.classList.toggle('selected',added);el.textContent=added?'✓ เลือกแล้ว':'＋ ขอราคา';el.setAttribute('aria-pressed',String(added))})}function save(){try{localStorage.setItem(key,JSON.stringify(basket))}catch{toast('เบราว์เซอร์ไม่อนุญาตบันทึกรายการ ข้อมูลจะอยู่ในหน้านี้เท่านั้น')}sync()}document.addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(!b)return;const id=b.dataset.add;if(basket.some(p=>p.id===id)){toast('สินค้านี้อยู่ในรายการขอราคาแล้ว');return}if(basket.length>=100){toast('เลือกได้สูงสุด 100 รายการต่อบรีฟ');return}basket.push({id,quantity:1});save();toast('เพิ่มสินค้าในรายการขอราคาแล้ว')});document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.src.endsWith('/assets/placeholder.svg')){e.target.src='/assets/placeholder.svg';e.target.alt+=' — ภาพต้นทางไม่พร้อมแสดง'}},true);const menu=$('#menu-toggle');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'ปิดเมนู':'เปิดเมนู');$('#main-navigation').classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu){menu.setAttribute('aria-expanded','false');$('#main-navigation').classList.remove('open')}});sync();window.addEventListener('storage',e=>{if(e.key===key)location.reload()});
function productCard(p){const title=p.titleTh||p.name;return `<article class="product-card"><a class="product-photo" href="${productUrl(p.id)}"><img src="${esc(p.image)}" alt="${esc(title)}" loading="lazy" width="400" height="350"></a><div class="product-body"><span class="sku">รหัสอ้างอิง ${sku(p.id)}</span><h3><a href="${productUrl(p.id)}">${esc(title)}</a></h3><div class="product-actions"><a href="${productUrl(p.id)}">รายละเอียด ↗</a><button class="add-product" data-add="${p.id}" aria-label="เพิ่ม ${esc(title)} ในรายการขอราคา">＋ ขอราคา</button></div></div></article>`}
const params=new URLSearchParams(location.search);const catNames={drinkware:'แก้วน้ำและกระบอกน้ำ',bag:'กระเป๋าและสิ่งทอ',technology:'อุปกรณ์เทคโนโลยี',office:'ของใช้สำนักงาน',lifestyle:'ของใช้ในชีวิตประจำวัน',eco:'ของพรีเมียมรักษ์โลก',apparel:'เสื้อผ้าและยูนิฟอร์ม',campaign:'ของสำหรับแคมเปญ','gift-set':'ชุดของขวัญพรีเมียม',packaging:'บรรจุภัณฑ์และกล่อง',seasonal:'สินค้าตามฤดูกาล',custom:'สั่งผลิตตามแบบ'};
function detail(id){if(/^\d+$/.test(id)){location.replace(base+'/products/gu-'+id)}else{$('#main').innerHTML='<section class="section container"><h1>ไม่พบสินค้ารหัสนี้</h1><a href="/smartgift/products">เลือกสินค้าในแค็ตตาล็อก</a></section>'}}
async function initCatalogue(){const area=$('[data-catalogue]');if(!area)return;if(params.has('item'))return detail(params.get('item'));let categoryInfo=[],all=[],category=params.get('category')||area.dataset.defaultCategory||'',query=params.get('q')||'',page=Math.max(1,Number(params.get('page'))||1);let sort=params.get('sort')||'new';const input=$('#product-search'),results=$('#product-results'),count=$('#catalog-count');input.value=query;$('#catalog-sort').value=sort;const size=24;function updateUrl(){const q=new URLSearchParams();if(category)q.set('category',category);if(query)q.set('q',query);if(page>1)q.set('page',page);if(sort!=='new')q.set('sort',sort);history.replaceState(null,'',location.pathname+(q.size?'?'+q:''))}function render(){const info=categoryInfo.find(c=>c.slug===category);const title=info?info.seoTitle:($('[data-catalogue]').dataset.defaultCategory==='gift-set'?'ชุดของขวัญองค์กร':'สินค้าพรีเมียม');document.title=title+' | SmartGift Thailand';if(info){$('.page-hero h1').textContent=info.name;$('.page-hero p').textContent=info.seoDescription;document.querySelector('meta[name=description]').content=info.seoDescription;}else{$('.page-hero h1').textContent='สินค้าพรีเมียม';$('.page-hero p').textContent='ค้นหาไอเดียสินค้าส่งเสริมการขายที่เหมาะกับแบรนด์และแคมเปญของคุณ';}const canonical=document.querySelector('link[rel=canonical]');if(canonical){const u=new URL(canonical.href);u.pathname=base+'/products';u.search=category?'?category='+category:'';canonical.href=u.href;}const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean);let list=all.filter(p=>(!category||p.categories.includes(category))&&words.every(w=>((p.titleTh||'')+' '+p.name+' '+p.id+' GU-'+p.id+' '+(p.descriptionTh||'')+' '+p.description+' '+p.categories.map(c=>catNames[c]).join(' ')).toLowerCase().includes(w)));if(sort==='name')list.sort((a,b)=>(a.titleTh||a.name).localeCompare(b.titleTh||b.name));else list.sort((a,b)=>Number(b.id)-Number(a.id));const pages=Math.max(1,Math.ceil(list.length/size));page=Math.min(page,pages);count.textContent=`${category?catNames[category]||category:'สินค้าทั้งหมด'} · ${list.length.toLocaleString('th-TH')} รายการ${query?' · “'+query+'”':''}`;document.querySelectorAll('[data-category]').forEach(a=>{const active=a.dataset.category===category;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')});results.innerHTML=list.length?list.slice((page-1)*size,page*size).map(productCard).join(''):`<div class="empty-state"><h2>ไม่พบสินค้าที่ตรงกับคำค้น</h2><p>ลองค้นด้วยชื่อสินค้า รหัส หรือเลือกหมวดอื่น</p><button id="reset-search" class="button outline">ล้างคำค้นและดูสินค้าทั้งหมด</button></div>`;$('#reset-search')?.addEventListener('click',()=>{query='';category='';input.value='';page=1;render()});const nums=[...new Set([1,page-1,page,page+1,pages])].filter(n=>n>0&&n<=pages).sort((a,b)=>a-b);$('#pagination').innerHTML=list.length?`<button ${page===1?'disabled':''} data-page="${page-1}" aria-label="หน้าก่อนหน้า">←</button>${nums.map((n,i)=>(i&&n>nums[i-1]+1?'<span>…</span>':'')+`<button data-page="${n}" ${page===n?'aria-current="page"':''} aria-label="หน้าที่ ${n}">${n}</button>`).join('')}<button ${page===pages?'disabled':''} data-page="${page+1}" aria-label="หน้าถัดไป">→</button>`:'';sync();updateUrl()}
area.addEventListener('click',e=>{const a=e.target.closest('[data-category]');if(a){e.preventDefault();category=a.dataset.category;page=1;render()}const b=e.target.closest('[data-page]');if(b){page=Number(b.dataset.page);render();$('.catalog-search').scrollIntoView({block:'start',behavior:'smooth'})}});$('.catalog-search').addEventListener('submit',e=>{e.preventDefault();query=input.value.trim();page=1;render()});let timer;input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{query=input.value.trim();page=1;render()},300)});$('#catalog-sort').addEventListener('change',e=>{sort=e.target.value;page=1;render()});try{categoryInfo=await fetchJson('/data/categories.json');all=await catalog();render()}catch{count.textContent='โหลดข้อมูลไม่สำเร็จ';results.innerHTML='<div class="error-block"><p>กรุณาตรวจการเชื่อมต่อแล้วลองโหลดรายการอีกครั้ง</p><button class="button teal" id="retry-catalog">ลองอีกครั้ง</button></div>';$('#retry-catalog').onclick=()=>location.reload()}}
async function getBasketItems(){if(!basket.length)return[];const list=await featured();const missing=basket.some(b=>!list.some(p=>p.id===b.id));const all=missing?await catalog():list;const activeIds=new Set(all.map(p=>p.id));const valid=basket.filter(b=>activeIds.has(b.id));if(valid.length!==basket.length){basket=valid;save();toast("นำสินค้าที่ไม่อยู่ในแค็ตตาล็อกออกจากรายการขอราคาแล้ว")}return basket.map(b=>({product:all.find(p=>p.id===b.id),id:b.id,quantity:b.quantity}))}
async function showBasket(){const el=$('#basket-content');if(!el)return;try{const items=await getBasketItems();el.innerHTML=items.length?items.map(({product:p,id,quantity})=>`<article class="basket-row"><img src="${esc(p?.image||'/assets/placeholder.svg')}" alt="${esc(p?.titleTh||p?.name||id)}" width="110" height="100"><div><h2><a href="${productUrl(id)}">${esc(p?.titleTh||p?.name||'GU-'+id)}</a></h2><p>${sku(id)} · ${p?.source==='SmartGift'?'สินค้าคัดสรรโดย SmartGift':'สินค้าอ้างอิงจาก GiftU'}</p></div><label>จำนวนที่ต้องการ<input aria-label="จำนวนสินค้า ${sku(id)}" type="number" min="1" max="10000000" value="${quantity}" data-quantity="${id}"></label><button class="remove-item" data-remove="${id}" aria-label="ลบสินค้า ${sku(id)}">ลบรายการ</button></article>`).join('')+'<button class="clear-basket">ล้างรายการทั้งหมด</button>':`<div class="empty-state"><h2>ยังไม่มีสินค้าในรายการ</h2><p>กด “ขอราคา” ที่สินค้าเพื่อรวบรวมรายการที่สนใจ</p><a class="button teal" href="${base}/products">เลือกสินค้า →</a></div>`;el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{basket=basket.filter(p=>p.id!==b.dataset.remove);save();showBasket()});el.querySelectorAll('[data-quantity]').forEach(n=>{n.addEventListener('input',()=>{const v=Number(n.value);if(Number.isInteger(v)&&v>=1&&v<=10000000){basket.find(p=>p.id===n.dataset.quantity).quantity=v;save()}});n.addEventListener('change',()=>{const v=Math.max(1,Math.min(10000000,Math.floor(Number(n.value)||1)));n.value=v;basket.find(p=>p.id===n.dataset.quantity).quantity=v;save()})});$('.clear-basket')?.addEventListener('click',()=>{basket=[];save();showBasket()})}catch{el.innerHTML='<div class="error-block">ไม่สามารถโหลดชื่อสินค้าได้ กรุณาลองใหม่ รายการที่เลือกยังเก็บไว้ในเบราว์เซอร์</div>'}}
const form=$('#brief-form');if(form){const today=new Date();form.elements.date.min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');if(params.get('sets'))form.elements.quantity.value=params.get('sets');if(params.get('set')){form.elements.detail.value=params.get('set').slice(0,2000);form.elements.quantity.value=params.get('sets')||'';form.elements.budget.value=params.get('budget')||'';}const uses={clients:'ชุดของขวัญสำหรับลูกค้าและคู่ค้า',employees:'ชุดของขวัญสำหรับพนักงานและทีมงาน',events:'ชุดของขวัญสำหรับงานอีเวนต์',seasonal:'ชุดของขวัญสำหรับเทศกาล'};if(uses[params.get('use')])form.elements.detail.value=uses[params.get('use')];if(params.get('product'))form.elements.product.value=params.get('product');form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector('button[type="submit"]');submit.disabled=true;try{const d=new FormData(form);let lines=['ขอปรึกษาโครงการกับ SmartGift',`ชื่อ: ${d.get('name')}`,`บริษัท/แบรนด์: ${d.get('company')||'-'}`,`ติดต่อกลับ: ${d.get('contact')}`,`โครงการ: ${d.get('purpose')}`,`จำนวน: ${d.get('quantity')||'ขอคำแนะนำ'}`,`งบประมาณ${d.get('budgetBasis')&&d.get('budgetBasis')!=='ขอคำแนะนำ'?' ('+d.get('budgetBasis')+')':''}: ${d.get('budget')||'ขอคำแนะนำ'}${d.get('budget')?' บาท':''}`,`วันใช้งาน: ${d.get('date')||'ยังไม่กำหนด'}`,`สินค้าที่สนใจ: ${d.get('product')||'-'}`,`รายละเอียด: ${d.get('detail')||'-'}`];if(basket.length){lines.push('','รายการสินค้าที่เลือก:');try{const items=await getBasketItems();items.forEach(({product:p,id,quantity})=>lines.push(`• ${sku(id)} ${p?.titleTh||p?.name||''} — ${quantity} ชิ้น/ชุด`))}catch{basket.forEach(p=>lines.push(`• ${sku(p.id)} — ${p.quantity} ชิ้น/ชุด`))}}$('#brief-text').value=lines.join('\n');$('#brief-output').hidden=false;$('#brief-output').scrollIntoView({behavior:'smooth',block:'center'});toast('เตรียมบรีฟแล้ว กรุณาคัดลอกและส่งผ่าน LINE')}finally{submit.disabled=false}});$('#copy-brief').addEventListener('click',async()=>{const text=$('#brief-text');try{await navigator.clipboard.writeText(text.value);$('#copy-status').textContent='คัดลอกแล้ว เปิด LINE แล้ววางข้อความเพื่อส่งให้ทีม';toast('คัดลอกบรีฟแล้ว')}catch{text.focus();text.select();$('#copy-status').textContent='กรุณาคัดลอกข้อความที่เลือก แล้วนำไปวางใน LINE'}})}
document.querySelectorAll('[data-feature]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-feature]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('.feature-panel').forEach(p=>p.classList.toggle('is-active',p.id==='feature-'+button.dataset.feature));}));document.querySelectorAll('[data-gallery-src]').forEach(button=>button.addEventListener('click',()=>{const gallery=button.closest('.product-gallery');const img=gallery.querySelector('[data-gallery-main]');img.src=button.dataset.gallerySrc;img.alt=button.dataset.galleryAlt;gallery.querySelector('[data-gallery-caption]').textContent=button.dataset.galleryNote;gallery.querySelectorAll('[data-gallery-src]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
const builder=$('[data-set-builder]');if(builder){const chosen=new Set();const items=[...builder.querySelectorAll('[data-build-add]')];const renderSet=()=>{items.forEach(b=>{const active=chosen.has(b.dataset.buildAdd);b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));b.textContent=active?'✓ อยู่ในชุดแล้ว':'＋ เพิ่มในชุด'});$('#builder-selection').innerHTML=chosen.size?'<ul>'+[...chosen].map(id=>{const b=items.find(b=>b.dataset.buildAdd===id);return '<li><span>'+esc(b.closest('.product-card').querySelector('h3').textContent)+'</span><button type="button" data-build-remove="'+id+'" aria-label="นำสินค้า GU-'+id+' ออกจากชุด">×</button></li>'}).join('')+'</ul>':'<p>กด “เพิ่มในชุด” ที่สินค้าที่สนใจ</p>';};builder.addEventListener('click',e=>{const add=e.target.closest('[data-build-add]'),remove=e.target.closest('[data-build-remove]');if(add){const id=add.dataset.buildAdd;chosen.has(id)?chosen.delete(id):chosen.add(id);renderSet()}if(remove){chosen.delete(remove.dataset.buildRemove);renderSet()}});$('#builder-form').addEventListener('submit',e=>{e.preventDefault();if(!chosen.size){$('#builder-status').textContent='กรุณาเลือกสินค้าอย่างน้อย 1 รายการ';return}const d=new FormData(e.target),sets=Math.max(1,Math.min(1000000,Math.floor(Number(d.get('sets'))||1)));if(basket.length+[...chosen].filter(id=>!basket.some(p=>p.id===id)).length>100){$('#builder-status').textContent='รายการขอราคาเกิน 100 รายการ กรุณาลดรายการก่อนบันทึกชุด';return}for(const id of chosen){const found=basket.find(p=>p.id===id);if(found)found.quantity=sets;else basket.push({id,quantity:sets})}save();const brief='ต้องการจัดชุดของขวัญ '+sets+' ชุด (สินค้าที่เลือกอย่างละ 1 ชิ้นต่อชุด)\nงบต่อชุด: '+(d.get('budget')||'ขอคำแนะนำ')+'\nแพ็กเกจ: '+d.get('packaging')+'\nผู้รับ/โอกาส: '+(d.get('occasion')||'ยังไม่ระบุ');location.href=base+'/contact?set='+encodeURIComponent(brief)+'&sets='+sets+'&budget='+encodeURIComponent(d.get('budget')||'');});}
initCatalogue();showBasket();})();
